    dots = [i for i, char in enumerate(string_value) if char == "."]
    if len(dots) == 0:
        return int(value)
    else:
        first_dot = dots[0]
        second_dot = dots[1]
        last_digit = first_dot + 1
        last_digit_value = int(string_value[last_digit])
        return (
            int(string_value[:first_dot])
            if last_digit_value < 5
            else int(string_value[:first_dot]) + 1
        )

