def max_fill(grid, capacity):
    import math
    def non_zero_rows(grid: List[List[int]]) -> List[int]:
        for i, row in enumerate(grid):
            if any(row):
                yield i

    def empty_columns(grid: List[List[int]], row: int) -> List[int]:
        for i, is_filled in enumerate(grid[row]):
            if is_filled:
                yield i

    def fill_well(grid: List[List[int]], row: int, bucket_capacity: int) -> int:
        filled_columns = 0
        for col in empty_columns(grid, row):
            filled_columns += 1
            grid[row][col] = 0
            bucket_capacity -= 1
            if bucket_capacity == 0:
                break
        return filled_columns

    bucket_capacity = capacity
    steps = 0
    for row in non_zero_rows(grid):
        steps += fill_well(grid, row, bucket_capacity)
        if bucket_capacity > 0:
            steps += 1
            bucket_capacity = capacity
    return steps

