            water = grid[i][j]
            if water > 0:
                drops = math.ceil(water / capacity)
                total_drops += drops
                fill_one_bucket = capacity * drops
                grid[i][j] -= fill_one_bucket
                for x, y in [(i - 1, j), (i + 1, j), (i, j - 1), (i, j + 1)]:
