def max_fill(grid, capacity):
    import math
    def get_max_row(grid: List[List[int]]) -> int:
        max_row = 0
        for row in grid:
            sum_row = sum(row)
            if sum_row > max_row:
                max_row = sum_row
        return max_row

    def fill_grid(grid: List[List[int]], max_fill: int) -> int:
        current_fill = 0
        while current_fill < max_fill:
            for i in range(len(grid)):
                for j in range(len(grid[i])):
                    if grid[i][j] == 1:
                        grid[i][j] = 0
                        current_fill += 1
                        if current_fill == max_fill:
                            return current_fill
        return current_fill

    # compute max row
    max_row = get_max_row(grid)
    # fill grid
    filled = fill_grid(grid, max_row * capacity)
    return filled

