def max_fill(grid, capacity):
    import math
    row_count = len(grid)
    col_count = len(grid[0])
    low_fill = 0
    for c in range(col_count):
        for r in range(row_count):
            if grid[r][c] != 0:
                continue
            for r2 in range(r+1, row_count):
                if grid[r2][c] == 0:
                    continue
                if grid[r2][c] <= capacity:
                    capacity -= grid[r2][c]
                    grid[r2][c] = 0
                    low_fill += 1
                else:
                    low_fill += 1
                    grid[r2][c] -= capacity
                    capacity = 0
                    break
            if capacity == 0:
                break
        capacity = 0
    return low_fill

