def max_fill(grid, capacity):
    import math
    # Initialize variables
    num_rows = len(grid)
    num_cols = len(grid[0])
    # Iterate over rows
    total_num_drops = 0
    for row in grid:
        # Find the rightmost well that needs filling
        rightmost_well = 0
        for well_idx in range(num_cols):
            if row[well_idx] > 0:
                rightmost_well = well_idx
        # Fill all wells to the right of the rightmost one
        if rightmost_well > 0:
            # Fill up the water to the capacity
            for well_idx in range(rightmost_well + 1):
                # Fill each well until the bucket is empty
                if row[well_idx] > 0:
                    current_water = capacity - row[well_idx]
                    row[well_idx] = capacity
                    total_num_drops += 1
                    while current_water > 0:
                        # Find the next well to fill
                        next_well = 0
                        for well_idx_2 in range(well_idx+1, num_cols):
                            if row[well_idx_2] > 0:
                                next_well = well_idx_2
                                break
                        # Fill the well
                        if next_well > 0:
                            row[next_well] += current_water
                            current_water = capacity - row[next_well]
                            row[next_well] = capacity
                            total_num_drops += 1
        # Fill the rightmost well up to capacity
        if row[rightmost_well] < capacity:
            total_num_drops += capacity - row[rightmost_well]
            row[rightmost_well] = capacity
    return total_num_drops

