def smallest_change(arr):
    n = len(arr)
    if n == 1:
        return 0
    if n == 2:
        return 1
    if n == 3:
        return min(1, abs(arr[0] - arr[2]))
    if n == 4:
        return min(2, abs(arr[0] - arr[2]) + abs(arr[1] - arr[3]))
    left = 0
    right = n - 1
    res = 0
    while left < right:
        res += abs(arr[left] - arr[right])
        left += 1
        right -= 1
    return res


