def smallest_change(arr):
    def is_palindrome(arr: List[int]) -> bool:
        left, right = 0, len(arr) - 1
        while left < right:
            if arr[left] != arr[right]:
                return False
            left += 1
            right -= 1
        return True

    def helper(arr: List[int], idx: int, count: int) -> int:
        if idx >= len(arr) // 2:
            return count

        left, right = idx, len(arr) - 1 - idx
        if arr[left] == arr[right]:
            return helper(arr, idx + 1, count)
        else:
            new_count_1 = helper(arr, idx + 1, count + 1)
            new_count_2 = helper(arr, idx + 1, count + 1)
            return min(new_count_1, new_count_2)

    if is_palindrome(arr):
        return 0
    return helper(arr, 0, 0)

