def check_dict_case(dict):
    # Split the dict into a keys list and a values list
    dict_keys = dict.keys()
    dict_values = dict.values()
    # If any keys are not strings, return False
    for key in dict_keys:
        if not isinstance(key, str):
            return False
    # If any values are not strings, return False
    for value in dict_values:
        if not isinstance(value, str):
            return False
    # If the dict is empty, return False
    if not dict:
        return False
    # Split the dict into a lower list and an upper list
    dict_lower = {k.lower(): v for k, v in dict.items()}
    dict_upper = {k.upper(): v for k, v in dict.items()}
    # If dict_keys and dict_lower are equal, return True
    if dict_keys == dict_lower:
        return True
    # If dict_keys and dict_upper are equal, return True
    elif dict_keys == dict_upper:
        return True
    # Otherwise, return False
    else:
        return False

