def rescale_to_unit(numbers: List[float]) -> List[float]:
    if not numbers:
        raise ValueError("Parameter 'numbers' can't be empty!")
    if len(numbers) == 1:
        raise ValueError("Parameter 'numbers' must contain at least two elements!")
    minimum = min(numbers)
    maximum = max(numbers)
    if (maximum - minimum) == 0:
        raise ValueError("All elements of the parameter 'numbers' are equal! Unable to rescale")
    return [ (x - minimum) / (maximum - minimum) for x in numbers ]

