def monotonic(l: list):
    # If a list has a single element it is monotonic by definition
    if len(l) == 1:
        return True
    # Create an iterator to "walk" through the list and track the last value
    it = iter(l)
    last = next(it)
    # Compare each subsequent value to the last
    for value in it:
        if value > last:
            increasing = True
            decreasing = False
        elif value < last:
            increasing = False
            decreasing = True
        else:
            increasing = False
            decreasing = False
        if increasing + decreasing == 1:
            last = value
        else:
            return False
    return True

