def is_nested(string):
    # have to have a closing bracket
    if ']' not in string:
        return False
    # have to have an opening bracket
    if '[' not in string:
        return False
    # if brackets count is 0 then there is no nested bracket
    if string.count('[') == string.count(']'):
        return False
    # if brackets count is uneven then there is a nested bracket
    if string.count('[') > string.count(']'):
        return True
    if string.count('[') < string.count(']'):
        return True
    # if input string is empty or has no brackets then false
    if string == '' or '[]' not in string:
        return False
    else:
        return False

