def minPath(grid, k):
    n = len(grid)
    offsets = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    dist = {}
    q = deque([(1, (0, 0))])
    dist[(0, 0)] = 0
    while q:
        v, pos = q.popleft()
        if v > k:
            break
        for i, j in offsets:
            new_pos = (pos[0] + i, pos[1] + j)
            if new_pos[0] < 0 or new_pos[0] >= n or new_pos[1] < 0 or new_pos[1] >= n:
                continue
            if new_pos not in dist or dist[new_pos] > v:
                dist[new_pos] = v
                q.append((v+1, new_pos))
    # construct path
    cur = (n-1, n-1)
    path = [grid[cur[0]][cur[1]]]
    while cur != (0, 0):
        for i, j in offsets:
            new_pos = (cur[0] + i, cur[1] + j)
            if new_pos[0] < 0 or new_pos[0] >= n or new_pos[1] < 0 or new_pos[1] >= n:
